const response = $input.first().json;
const dados = $('Prepara Dados do Evento').first().json;
const items = response.items || [];

// Remove acentos para comparação
function norm(s) {
  return (s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim();
}

const nameKey = norm(dados.client_name);
const nameParts = nameKey.split(/\s+/).filter(p => p.length > 2);

const duplicate = items.find(ev => {
  const title = norm(ev.summary);
  return nameParts.length > 0 && nameParts.some(part => title.includes(part));
});

if (duplicate) {
  return [{ json: {
    duplicado: true,
    mensagem: 'Já existe um agendamento para ' + dados.client_name + ' em ' + dados.dateDisplay + ' às ' + dados.time + '. Agendamento não duplicado. Para reagendar, cancele o anterior primeiro.'
  } }];
}

return [{ json: { duplicado: false, ...dados } }];

const msg = ($('Coleta').first().json.mensagem || '').trim();

// Extract phone: "AVALIAÇÃO 11999887766" or "AVALIACAO 5511999887766"
const parts = msg.split(/\s+/);
let phone = (parts[1] || '').replace(/\D/g, '');

