const outputTokens = usage.output_tokens || 0;

// Preços Claude Sonnet 4.6 (USD por 1M tokens) - Maio 2026
const PRICE_INPUT = 3.00;
const PRICE_OUTPUT = 15.00;
const PRICE_CACHE_WRITE = 3.75;  // 1.25x input
const PRICE_CACHE_READ = 0.30;   // 0.1x input (90% off)

const cost = (
  (inputTokens * PRICE_INPUT) +
  (cacheCreation * PRICE_CACHE_WRITE) +
  (cacheRead * PRICE_CACHE_READ) +
  (outputTokens * PRICE_OUTPUT)
) / 1000000;

