// Extrai métricas de uso da resposta do Claude
const resp = $input.first().json;
const usage = resp.usage || {};

const inputTokens = usage.input_tokens || 0;
const cacheCreation = usage.cache_creation_input_tokens || 0;
const cacheRead = usage.cache_read_input_tokens || 0;
const outputTokens = usage.output_tokens || 0;

// Preços Claude Sonnet 4.6 (USD por 1M tokens) - Maio 2026
const PRICE_INPUT = 3.00;
const PRICE_OUTPUT = 15.00;
const PRICE_CACHE_WRITE = 3.75;  // 1.25x input
const PRICE_CACHE_READ = 0.30;   // 0.1x input (90% off)

const cost = (
  (inputTokens * PRICE_INPUT) +
  (cacheCreation * PRICE_CACHE_WRITE) +
  (cacheRead * PRICE_CACHE_READ) +
  (outputTokens * PRICE_OUTPUT)
) / 1000000;

// Recupera telefone do nó Coleta (origem da conversa)
let telefone = '';
try {
  telefone = ($('Coleta').first().json.telefone || '').replace('@s.whatsapp.net', '');
} catch(e) {}

return [{
  json: {
    telefone,
    iteracao: 1,
    modelo: resp.model || 'claude-sonnet-4-6',
    input_tokens: inputTokens,
    cache_creation_tokens: cacheCreation,
    cache_read_tokens: cacheRead,
    output_tokens: outputTokens,
    custo_estimado_usd: cost.toFixed(8),
    stop_reason: resp.stop_reason || 'unknown'
  }
}];

